// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** A soft coloured glow behind an image or a card. It takes its colours from a list you give, or from a blurred, enlarged copy of the content itself. */
export interface BacklightSpecProps {
  /**
   * The image or card the glow sits behind.
   */
  children: ReactNode;
  /**
   * Glow colours, any CSS colours. Leave out to use a blurred copy of the children instead.
   */
  colors?: string[];
  /**
   * How strong the glow is, from 0 to 1.
   * @default 0.6
   */
  intensity?: number;
  /**
   * Blur radius of the glow in pixels.
   * @default 40
   */
  blur?: number;
  /**
   * How much larger than the content the glow is.
   * @default 1.1
   */
  scale?: number;
  /**
   * Seconds for one slow cycle of the glow.
   * @default 14
   */
  duration?: number;
  /**
   * Keeps the glow still instead of slowly moving.
   * @default false
   */
  isStill?: boolean;
}

export const backlightDefaults = {
  intensity: 0.6,
  blur: 40,
  scale: 1.1,
  duration: 14,
  isStill: false,
} as const;

export const backlightMeta = {
  "name": "Backlight",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;
